std::vector<std::uint8_t> unhex(const std::string& text){require(text.size()%2==0,"Odd native cache hex");std::vector<std::uint8_t> bytes;for(std::size_t i=0;i<text.size();i+=2){const auto nibble=[](char c)->unsigned{if(c>='0'&&c<='9')return unsigned(c-'0');if(c>='a'&&c<='f')return unsigned(c-'a'+10);throw std::runtime_error("Invalid native cache hex");};bytes.push_back(static_cast<std::uint8_t>(nibble(text[i])*16+nibble(text[i+1])));}return bytes;}
